INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Muss ein Switch immer einen Default-Case haben?', 2, '[{"text": "Nein", "correct": true, "because": "Default ist optional"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Switch?', 3, '[{"text": "Mehrere Fälle prüfen", "correct": true, "because": "Verzweigt nach Wert"}, {"text": "Wiederholung steuern", "correct": false, "because": "Für Schleifen"}, {"text": "Datenbank abfragen", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Switch?', 5, '[{"text": "Cases", "correct": true, "because": "Definieren Verzweigungen"}, {"text": "Ausdruck", "correct": true, "because": "Wert wird geprüft"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}, {"text": "Netzwerkprotokoll", "correct": false, "because": "Kein Kernbestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Switch ersetzt If-Else. b) Cases müssen einzigartig sein.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "a) ist kontextabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "Switch ergänzt If"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Switch?', 4, '[{"text": "Case-Werte", "correct": false, "because": "Steuern Verzweigung"}, {"text": "Break-Anweisung", "correct": false, "because": "Vermeidet Fall-through"}, {"text": "Bildauflösung", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Switch nur Zahlen prüft?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Strings möglich"}, {"text": "Ja", "correct": false, "because": "Sprachabhängig flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Befehl wähle ich, um einen Case zu beenden?', 3, '[{"text": "break", "correct": true, "because": "Stoppt Ausführung"}, {"text": "continue", "correct": false, "because": "Für Schleifen"}, {"text": "return", "correct": false, "because": "Funktion beenden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Switch?', 5, '[{"text": "Lesbarkeit", "correct": true, "because": "Klar strukturiert"}, {"text": "Effizienz bei vielen Fällen", "correct": true, "because": "Schneller als If-Else"}, {"text": "Datenkompression", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Switch ist schneller als If. b) Default ist Pflicht. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Default optional"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) oft richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Switch?', 4, '[{"text": "Ausdruck zum Prüfen", "correct": false, "because": "Grundlage der Fälle"}, {"text": "Case-Anweisungen", "correct": false, "because": "Definieren Verzweigungen"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Switch ohne break laufen?', 2, '[{"text": "Ja", "correct": true, "because": "Führt zu Fall-through"}, {"text": "Nein", "correct": false, "because": "Technisch möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Steuerungsmöglichkeiten habe ich in einem Switch?', 4, '[{"text": "Break", "correct": true, "because": "Beendet Case"}, {"text": "Default", "correct": true, "because": "Fängt Rest ab"}, {"text": "Loop", "correct": false, "because": "Schleifen-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Switch nur für einfache Werte ist. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Meist primitive Typen"}, {"text": "Nein", "correct": false, "because": "Sprachabhängig erweiterbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Switch?', 3, '[{"text": "Klarheit der Cases", "correct": true, "because": "Fördert Verständnis"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Korrektheit zählt"}, {"text": "UI-Optimierung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Switch reduziert Code. b) Cases können doppelt sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) führt zu Fehlern"}, {"text": "Beides stimmt", "correct": false, "because": "Cases einzigartig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es bei einem Switch?', 5, '[{"text": "Fall-through", "correct": true, "because": "Ohne break möglich"}, {"text": "Fehlender Default", "correct": true, "because": "Unbehandelte Fälle"}, {"text": "Schnellere Builds", "correct": false, "because": "Kein Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Switch unwichtig?', 3, '[{"text": "Case-Definition", "correct": false, "because": "Steuert Verzweigung"}, {"text": "Break-Nutzung", "correct": false, "because": "Kontrolliert Ablauf"}, {"text": "Serverleistung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Prüft Switch mehrere Bedingungen pro Case?', 3, '[{"text": "Nein", "correct": true, "because": "Nur ein Wert pro Case"}, {"text": "Ja", "correct": false, "because": "If-Else für Komplexes"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Switch in jeder Sprache gleich ist?', 2, '[{"text": "Nein", "correct": true, "because": "Syntax variiert"}, {"text": "Ja", "correct": false, "because": "Sprachabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Fall wähle ich für unbehandelte Werte?', 4, '[{"text": "default", "correct": true, "because": "Fängt Rest ab"}, {"text": "break", "correct": false, "because": "Beendet nur"}, {"text": "case", "correct": false, "because": "Spezifischer Wert"}]');
